package org.apache.flink.types;

import org.apache.flink.core.memory.DataInputDeserializer;
import org.apache.flink.core.memory.DataInputView;
import org.apache.flink.core.memory.DataOutputSerializer;
import org.apache.flink.core.memory.DataOutputView;

import org.junit.jupiter.api.Test;

import java.io.IOException;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link Record#unionFields(Record)}. */
class RecordUnionFieldsTests {

    @Test
    void unionUsesNonNullFieldFromThisAndFillsNullFromOther() {
        Record left = syncedRecord(new IntValue(10), null);
        Record right = syncedRecord(new IntValue(20), new StringValue("from-right"));

        left.unionFields(right);

        assertEquals(2, left.getNumFields());
        assertIntField(left, 0, 10);
        assertStringField(left, 1, "from-right");
        assertFalse(left.isNull(0));
        assertFalse(left.isNull(1));

        // The other record must not be changed by the union.
        assertIntField(right, 0, 20);
        assertStringField(right, 1, "from-right");
    }

    @Test
    void unionKeepsNullWhenBothRecordsHaveNullField() {
        Record left = syncedRecord(null, new StringValue("left"));
        Record right = syncedRecord(new IntValue(99), null);

        left.unionFields(right);

        assertEquals(2, left.getNumFields());
        assertIntField(left, 0, 99);
        assertStringField(left, 1, "left");
    }

    @Test
    void unionAppendsTrailingFieldsWhenThisHasMoreFields() {
        Record left =
                syncedRecord(
                        new IntValue(1), null, new StringValue("tail-left"), new LongValue(4L));
        Record right = syncedRecord(new IntValue(99), new StringValue("right"));

        left.unionFields(right);

        assertEquals(4, left.getNumFields());
        assertIntField(left, 0, 1);
        assertStringField(left, 1, "right");
        assertStringField(left, 2, "tail-left");
        assertLongField(left, 3, 4L);
    }

    @Test
    void unionAppendsTrailingFieldsWhenOtherHasMoreFields() {
        Record left = syncedRecord(new IntValue(1), null);
        Record right =
                syncedRecord(
                        new IntValue(99), new StringValue("right"), null, new DoubleValue(4.5d));

        left.unionFields(right);

        assertEquals(4, left.getNumFields());
        assertIntField(left, 0, 1);
        assertStringField(left, 1, "right");
        assertTrue(left.isNull(2));
        assertNull(left.getField(2, StringValue.class));
        assertDoubleField(left, 3, 4.5d);
    }

    @Test
    void unionSerializesModifiedFieldsFromThisAndCopiesUnmodifiedBinaryFields() {
        Record left = syncedRecord(new IntValue(1), new StringValue("left-middle"), null);
        left.setField(0, new IntValue(7));
        left.setField(2, new StringValue("left-new"));

        Record right =
                syncedRecord(
                        new IntValue(99),
                        new StringValue("right-middle"),
                        new StringValue("right-last"));

        left.unionFields(right);

        assertEquals(3, left.getNumFields());
        assertIntField(left, 0, 7);
        assertStringField(left, 1, "left-middle");
        assertStringField(left, 2, "left-new");
    }

    @Test
    void unionUsesModifiedFieldFromOtherOnlyForNullFieldsInThis() {
        Record left = syncedRecord(null, new StringValue("left-middle"), null);
        Record right = syncedRecord(new IntValue(100), new StringValue("right-middle"), null);
        right.setField(0, new IntValue(42));
        right.setField(2, new StringValue("other-new"));

        left.unionFields(right);

        assertEquals(3, left.getNumFields());
        assertIntField(left, 0, 42);
        assertStringField(left, 1, "left-middle");
        assertStringField(left, 2, "other-new");
    }

    @Test
    void unionUsesModifiedNullAndBinaryTrailingFieldsFromOther() {
        Record left = syncedRecord(new IntValue(1));
        Record right =
                syncedRecord(
                        new IntValue(9), null, new StringValue("other-two"), new LongValue(4L));
        right.setField(1, new StringValue("modified-trailing"));
        right.setField(3, null);

        left.unionFields(right);

        assertEquals(4, left.getNumFields());
        assertIntField(left, 0, 1);
        assertStringField(left, 1, "modified-trailing");
        assertStringField(left, 2, "other-two");
        assertTrue(left.isNull(3));
    }

    @Test
    void unionUsesModifiedTrailingFieldsFromThis() {
        Record left =
                syncedRecord(new IntValue(1), new StringValue("left-one"), null, new LongValue(4L));
        left.setField(2, new StringValue("modified-tail"));
        Record right = syncedRecord(new IntValue(99), new StringValue("right"));

        left.unionFields(right);

        assertEquals(4, left.getNumFields());
        assertIntField(left, 0, 1);
        assertStringField(left, 1, "left-one");
        assertStringField(left, 2, "modified-tail");
        assertLongField(left, 3, 4L);
    }

    @Test
    void unionSupportsEmptyRecordsWithAllocatedFieldArrays() {
        Record left = syncedRecord(new IntValue(5), new StringValue("old"));
        left.clear();
        Record right = syncedRecord(new IntValue(11), new StringValue("new"));

        left.unionFields(right);

        assertEquals(2, left.getNumFields());
        assertIntField(left, 0, 11);
        assertStringField(left, 1, "new");
    }

    @Test
    void unionPreservesFieldsAcrossMoreThanEightColumnsAndRoundTrips() throws IOException {
        Value[] leftValues = new Value[9];
        Value[] rightValues = new Value[9];
        leftValues[0] = null;
        rightValues[0] = new StringValue("right-zero");
        for (int i = 1; i < 9; i++) {
            leftValues[i] = new StringValue("left-" + i + "--------------------------------");
            rightValues[i] = new StringValue("right-" + i + "-------------------------------");
        }

        Record left = syncedRecord(leftValues);
        Record right = syncedRecord(rightValues);
        left.unionFields(right);

        assertEquals(9, left.getNumFields());
        assertStringField(left, 0, "right-zero");
        for (int i = 1; i < 9; i++) {
            assertStringField(left, i, "left-" + i + "--------------------------------");
        }

        DataOutputSerializer output = new DataOutputSerializer(256);
        left.write(output);
        DataInputDeserializer input =
                new DataInputDeserializer(output.getCopyOfBuffer(), 0, output.length());
        Record deserialized = new Record();
        deserialized.read(input);

        assertEquals(9, deserialized.getNumFields());
        assertStringField(deserialized, 0, "right-zero");
        for (int i = 1; i < 9; i++) {
            assertStringField(deserialized, i, "left-" + i + "--------------------------------");
        }
    }

    @Test
    void unionCanBeAppliedRepeatedlyWithReusedBuffers() {
        Record target = syncedRecord(new IntValue(1), null);
        target.unionFields(syncedRecord(null, new StringValue("second")));

        assertIntField(target, 0, 1);
        assertStringField(target, 1, "second");

        target.setField(0, null);
        target.unionFields(syncedRecord(new IntValue(7), new StringValue("ignored")));

        assertEquals(2, target.getNumFields());
        assertIntField(target, 0, 7);
        assertStringField(target, 1, "second");
    }

    @Test
    void unionRejectsNullOtherRecord() {
        Record record = syncedRecord(new IntValue(1));

        assertThrows(NullPointerException.class, () -> record.unionFields(null));
        assertEquals(1, record.getNumFields());
        assertIntField(record, 0, 1);
    }

    @Test
    void unionWrapsFailuresWhileSerializingModifiedFields() {
        FailingValue failingValue = new FailingValue();
        Record left = new Record(1);
        left.setField(0, failingValue);
        Record right = syncedRecord(new IntValue(2));

        RuntimeException exception =
                assertThrows(RuntimeException.class, () -> left.unionFields(right));

        assertInstanceOf(IOException.class, exception.getCause());
        assertEquals("write failed", exception.getCause().getMessage());
        assertTrue(exception.getMessage().contains("write failed"));
        assertEquals(1, left.getNumFields());
    }

    private static Record syncedRecord(Value... values) {
        Record record = new Record(values.length);
        for (int i = 0; i < values.length; i++) {
            record.setField(i, values[i]);
        }
        record.updateBinaryRepresenation();
        return record;
    }

    private static void assertIntField(Record record, int field, int expected) {
        IntValue value = record.getField(field, IntValue.class);
        assertNotNull(value);
        assertEquals(expected, value.getValue());
    }

    private static void assertLongField(Record record, int field, long expected) {
        LongValue value = record.getField(field, LongValue.class);
        assertNotNull(value);
        assertEquals(expected, value.getValue());
    }

    private static void assertDoubleField(Record record, int field, double expected) {
        DoubleValue value = record.getField(field, DoubleValue.class);
        assertNotNull(value);
        assertEquals(expected, value.getValue());
    }

    private static void assertStringField(Record record, int field, String expected) {
        StringValue value = record.getField(field, StringValue.class);
        assertNotNull(value);
        assertEquals(expected, value.getValue());
    }

    private static final class FailingValue implements Value {
        private static final long serialVersionUID = 1L;

        @Override
        public void write(DataOutputView out) throws IOException {
            throw new IOException("write failed");
        }

        @Override
        public void read(DataInputView in) throws IOException {
            throw new IOException("read failed");
        }
    }
}

