/** Tests for {@link ParquetSplitReaderUtil#createWritableColumnVector}. */
class ParquetSplitReaderUtilCreateWritableColumnVectorTests {

    private static final int DEFAULT_BATCH_SIZE = 5;

    @Test
    void testBooleanVectorMappingAndUsage() {
        PrimitiveType primitive = primitive("flag", PrimitiveTypeName.BOOLEAN);
        WritableColumnVector vector =
                create(
                        DEFAULT_BATCH_SIZE,
                        new BooleanType(),
                        primitive,
                        descriptor(new String[] {"flag"}, primitive));

        assertVector(vector, HeapBooleanVector.class, DEFAULT_BATCH_SIZE);

        HeapBooleanVector booleanVector = (HeapBooleanVector) vector;
        booleanVector.setBoolean(0, true);
        booleanVector.setBoolean(1, false);
        booleanVector.setNullAt(2);

        assertThat(booleanVector.getBoolean(0)).isTrue();
        assertThat(booleanVector.getBoolean(1)).isFalse();
        assertThat(booleanVector.isNullAt(2)).isTrue();
        assertThat(booleanVector.isNullAt(3)).isFalse();
    }

    @ParameterizedTest(name = "{0} with parquet type {1} -> {2}")
    @MethodSource("primitiveTypeCases")
    void testPrimitiveTypeMapping(
            LogicalType fieldType, PrimitiveTypeName typeName, Class<?> expectedVectorClass) {
        PrimitiveType primitive = primitive("field", typeName);
        WritableColumnVector vector =
                create(
                        DEFAULT_BATCH_SIZE,
                        fieldType,
                        primitive,
                        descriptor(new String[] {"field"}, primitive));

        assertVector(vector, expectedVectorClass, DEFAULT_BATCH_SIZE);
    }

    private static Stream<Arguments> primitiveTypeCases() {
        return Stream.of(
                Arguments.of(new BooleanType(), PrimitiveTypeName.BOOLEAN, HeapBooleanVector.class),
                Arguments.of(new TinyIntType(), PrimitiveTypeName.INT32, HeapByteVector.class),
                Arguments.of(new SmallIntType(), PrimitiveTypeName.INT32, HeapShortVector.class),
                Arguments.of(new IntType(), PrimitiveTypeName.INT32, HeapIntVector.class),
                Arguments.of(new DateType(), PrimitiveTypeName.INT32, HeapIntVector.class),
                Arguments.of(new TimeType(), PrimitiveTypeName.INT32, HeapIntVector.class),
                Arguments.of(new BigIntType(), PrimitiveTypeName.INT64, HeapLongVector.class),
                Arguments.of(new FloatType(), PrimitiveTypeName.FLOAT, HeapFloatVector.class),
                Arguments.of(new DoubleType(), PrimitiveTypeName.DOUBLE, HeapDoubleVector.class),
                Arguments.of(new CharType(10), PrimitiveTypeName.BINARY, HeapBytesVector.class),
                Arguments.of(new VarCharType(10), PrimitiveTypeName.BINARY, HeapBytesVector.class),
                Arguments.of(new BinaryType(10), PrimitiveTypeName.BINARY, HeapBytesVector.class),
                Arguments.of(
                        new VarBinaryType(10), PrimitiveTypeName.BINARY, HeapBytesVector.class),
                Arguments.of(
                        new TimestampType(), PrimitiveTypeName.INT96, HeapTimestampVector.class),
                Arguments.of(
                        new TimestampType(), PrimitiveTypeName.INT64, HeapTimestampVector.class),
                Arguments.of(
                        new LocalZonedTimestampType(),
                        PrimitiveTypeName.INT96,
                        HeapTimestampVector.class),
                Arguments.of(
                        new LocalZonedTimestampType(),
                        PrimitiveTypeName.INT64,
                        HeapTimestampVector.class));
    }

    @ParameterizedTest(name = "decimal precision {0} with parquet type {1} -> {2}")
    @MethodSource("decimalTypeCases")
    void testDecimalTypeMapping(
            int precision, PrimitiveTypeName typeName, Class<?> expectedVectorClass) {
        PrimitiveType primitive = decimalPrimitive("dec", typeName);
        WritableColumnVector vector =
                create(
                        DEFAULT_BATCH_SIZE,
                        new DecimalType(precision, Math.min(2, precision)),
                        primitive,
                        descriptor(new String[] {"dec"}, primitive));

        assertVector(vector, expectedVectorClass, DEFAULT_BATCH_SIZE);
    }

    private static Stream<Arguments> decimalTypeCases() {
        return Stream.of(
                // 32 bit decimals
                Arguments.of(1, PrimitiveTypeName.INT32, HeapIntVector.class),
                Arguments.of(9, PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY, HeapIntVector.class),
                // 64 bit decimals
                Arguments.of(10, PrimitiveTypeName.INT64, HeapLongVector.class),
                Arguments.of(18, PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY, HeapLongVector.class),
                // 128 bit decimals
                Arguments.of(19, PrimitiveTypeName.BINARY, HeapBytesVector.class),
                Arguments.of(38, PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY, HeapBytesVector.class));
    }

    @Test
    void testArrayOfPrimitiveType() {
        PrimitiveType primitive = primitive("arr", PrimitiveTypeName.INT32);
        WritableColumnVector vector =
                create(
                        DEFAULT_BATCH_SIZE,
                        new ArrayType(new IntType()),
                        primitive,
                        descriptor(new String[] {"arr"}, primitive));

        assertVector(vector, HeapArrayVector.class, DEFAULT_BATCH_SIZE);
        ColumnVector child = ((HeapArrayVector) vector).getChild();
        assertVector(child, HeapIntVector.class, DEFAULT_BATCH_SIZE);

        HeapIntVector childVector = (HeapIntVector) child;
        childVector.setInt(3, 13);
        assertThat(childVector.getInt(3)).isEqualTo(13);
    }

    @Test
    void testNestedArrayType() {
        PrimitiveType primitive = primitive("arr", PrimitiveTypeName.DOUBLE);
        WritableColumnVector vector =
                create(
                        DEFAULT_BATCH_SIZE,
                        new ArrayType(new ArrayType(new DoubleType())),
                        primitive,
                        descriptor(new String[] {"arr"}, primitive));

        assertVector(vector, HeapArrayVector.class, DEFAULT_BATCH_SIZE);
        ColumnVector nested = ((HeapArrayVector) vector).getChild();
        assertVector(nested, HeapArrayVector.class, DEFAULT_BATCH_SIZE);
        assertVector(
                ((HeapArrayVector) nested).getChild(), HeapDoubleVector.class, DEFAULT_BATCH_SIZE);
    }

    @Test
    void testMapType() {
        GroupType mapType = mapGroupType("m", PrimitiveTypeName.INT32, PrimitiveTypeName.DOUBLE);
        PrimitiveType keyPrimitive = primitive("key", PrimitiveTypeName.INT32);
        PrimitiveType valuePrimitive = primitive("value", PrimitiveTypeName.DOUBLE);
        List<ColumnDescriptor> descriptors =
                Arrays.asList(
                        descriptor(new String[] {"m", "key_value", "key"}, keyPrimitive),
                        descriptor(new String[] {"m", "key_value", "value"}, valuePrimitive));

        WritableColumnVector vector =
                create(
                        DEFAULT_BATCH_SIZE,
                        new MapType(new IntType(), new DoubleType()),
                        mapType,
                        descriptors);

        assertVector(vector, HeapMapVector.class, DEFAULT_BATCH_SIZE);
        HeapMapVector mapVector = (HeapMapVector) vector;
        assertVector(mapVector.getKeyColumnVector(), HeapIntVector.class, DEFAULT_BATCH_SIZE);
        assertVector(mapVector.getValueColumnVector(), HeapDoubleVector.class, DEFAULT_BATCH_SIZE);
    }

    @Test
    void testMapTypeWrappedInList() {
        GroupType innerMap =
                Types.requiredGroup()
                        .as(LogicalTypeAnnotation.mapType())
                        .addField(
                                Types.requiredGroup()
                                        .addField(
                                                Types.required(PrimitiveTypeName.INT32)
                                                        .named("key"))
                                        .addField(
                                                Types.required(PrimitiveTypeName.DOUBLE)
                                                        .named("value"))
                                        .named("key_value"))
                        .named("map");
        GroupType listGroup = Types.repeatedGroup().addField(innerMap).named("list");
        GroupType outerList =
                Types.requiredGroup()
                        .as(LogicalTypeAnnotation.listType())
                        .addField(listGroup)
                        .named("m");

        List<ColumnDescriptor> descriptors =
                Arrays.asList(
                        descriptor(
                                new String[] {"m", "list", "map", "key_value", "key"},
                                primitive("key", PrimitiveTypeName.INT32)),
                        descriptor(
                                new String[] {"m", "list", "map", "key_value", "value"},
                                primitive("value", PrimitiveTypeName.DOUBLE)));

        WritableColumnVector vector =
                create(
                        DEFAULT_BATCH_SIZE,
                        new MapType(new IntType(), new DoubleType()),
                        outerList,
                        descriptors);

        assertVector(vector, HeapMapVector.class, DEFAULT_BATCH_SIZE);
        HeapMapVector mapVector = (HeapMapVector) vector;
        assertVector(mapVector.getKeyColumnVector(), HeapIntVector.class, DEFAULT_BATCH_SIZE);
        assertVector(mapVector.getValueColumnVector(), HeapDoubleVector.class, DEFAULT_BATCH_SIZE);
    }

    @Test
    void testMultisetType() {
        GroupType multisetType =
                Types.requiredGroup()
                        .as(LogicalTypeAnnotation.mapType())
                        .addField(
                                Types.requiredGroup()
                                        .addField(
                                                Types.required(PrimitiveTypeName.INT64)
                                                        .named("element"))
                                        .addField(
                                                Types.required(PrimitiveTypeName.INT32)
                                                        .named("value"))
                                        .named("key_value"))
                        .named("ms");
        PrimitiveType elementPrimitive = primitive("element", PrimitiveTypeName.INT64);
        PrimitiveType valuePrimitive = primitive("value", PrimitiveTypeName.INT32);
        List<ColumnDescriptor> descriptors =
                Arrays.asList(
                        descriptor(new String[] {"ms", "key_value", "element"}, elementPrimitive),
                        descriptor(new String[] {"ms", "key_value", "value"}, valuePrimitive));

        WritableColumnVector vector =
                create(
                        DEFAULT_BATCH_SIZE,
                        new MultisetType(new BigIntType()),
                        multisetType,
                        descriptors);

        assertVector(vector, HeapMapVector.class, DEFAULT_BATCH_SIZE);
        HeapMapVector mapVector = (HeapMapVector) vector;
        assertVector(mapVector.getKeyColumnVector(), HeapLongVector.class, DEFAULT_BATCH_SIZE);
        // The counts of a multiset are always represented as INT.
        assertVector(mapVector.getValueColumnVector(), HeapIntVector.class, DEFAULT_BATCH_SIZE);
    }

    @Test
    void testRowType() {
        GroupType rowType =
                Types.requiredGroup()
                        .addField(Types.required(PrimitiveTypeName.INT32).named("a"))
                        .addField(Types.required(PrimitiveTypeName.DOUBLE).named("b"))
                        .named("r");
        List<ColumnDescriptor> descriptors =
                Arrays.asList(
                        descriptor(new String[] {"r", "a"}, PrimitiveTypeName.INT32),
                        descriptor(new String[] {"r", "b"}, PrimitiveTypeName.DOUBLE));

        WritableColumnVector vector =
                create(
                        DEFAULT_BATCH_SIZE,
                        RowType.of(new IntType(), new DoubleType()),
                        rowType,
                        descriptors);

        assertVector(vector, HeapRowVector.class, DEFAULT_BATCH_SIZE);
        WritableColumnVector[] fields = ((HeapRowVector) vector).getFields();
        assertThat(fields).hasSize(2);
        assertVector(fields[0], HeapIntVector.class, DEFAULT_BATCH_SIZE);
        assertVector(fields[1], HeapDoubleVector.class, DEFAULT_BATCH_SIZE);
    }

    @Test
    void testRowTypeWrappedInList() {
        GroupType elementGroup =
                Types.requiredGroup()
                        .addField(Types.required(PrimitiveTypeName.INT32).named("a"))
                        .named("element");
        GroupType listGroup = Types.repeatedGroup().addField(elementGroup).named("list");
        GroupType outerList =
                Types.requiredGroup()
                        .as(LogicalTypeAnnotation.listType())
                        .addField(listGroup)
                        .named("r");

        WritableColumnVector vector =
                create(
                        DEFAULT_BATCH_SIZE,
                        RowType.of(new IntType()),
                        outerList,
                        Collections.singletonList(
                                descriptor(
                                        new String[] {"r", "list", "element", "a"},
                                        PrimitiveTypeName.INT32)));

        assertVector(vector, HeapRowVector.class, DEFAULT_BATCH_SIZE);
        WritableColumnVector[] fields = ((HeapRowVector) vector).getFields();
        assertThat(fields).hasSize(1);
        assertVector(fields[0], HeapIntVector.class, DEFAULT_BATCH_SIZE);
    }

    @Test
    void testZeroBatchSize() {
        WritableColumnVector vector =
                create(
                        0,
                        new IntType(),
                        primitive("id", PrimitiveTypeName.INT32),
                        descriptor(new String[] {"id"}, PrimitiveTypeName.INT32));

        assertVector(vector, HeapIntVector.class, 0);
    }

    @ParameterizedTest(name = "invalid primitive type for {0}")
    @MethodSource("invalidPrimitiveTypeCases")
    void testMismatchedPrimitiveTypeThrows(
            LogicalType fieldType, PrimitiveTypeName actualTypeName) {
        PrimitiveType primitive = primitive("field", actualTypeName);

        assertThatThrownBy(
                        () ->
                                create(
                                        DEFAULT_BATCH_SIZE,
                                        fieldType,
                                        primitive,
                                        descriptor(new String[] {"field"}, primitive)))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("Unexpected type")
                .hasMessageContaining(actualTypeName.name());
    }

    private static Stream<Arguments> invalidPrimitiveTypeCases() {
        return Stream.of(
                Arguments.of(new BooleanType(), PrimitiveTypeName.INT32),
                Arguments.of(new IntType(), PrimitiveTypeName.DOUBLE),
                Arguments.of(new BigIntType(), PrimitiveTypeName.INT32),
                Arguments.of(new DoubleType(), PrimitiveTypeName.FLOAT),
                Arguments.of(new VarCharType(5), PrimitiveTypeName.INT32),
                Arguments.of(new TimestampType(), PrimitiveTypeName.BINARY));
    }

