    // ------------------------------------------------------------------------
    //  Helpers
    // ------------------------------------------------------------------------

    private static WritableColumnVector create(
            int batchSize, LogicalType fieldType, Type type, ColumnDescriptor descriptor) {
        return create(batchSize, fieldType, type, Collections.singletonList(descriptor));
    }

    private static WritableColumnVector create(
            int batchSize, LogicalType fieldType, Type type, List<ColumnDescriptor> descriptors) {
        return ParquetSplitReaderUtil.createWritableColumnVector(
                batchSize, fieldType, type, descriptors, 0);
    }

    private static void assertVector(
            ColumnVector vector, Class<?> expectedClass, int expectedBatchSize) {
        assertThat(vector).isInstanceOf(expectedClass);
        assertThat(((AbstractHeapVector) vector).getLen()).isEqualTo(expectedBatchSize);
    }

    private static PrimitiveType primitive(String name, PrimitiveTypeName typeName) {
        return new PrimitiveType(Type.Repetition.OPTIONAL, typeName, name);
    }

    private static PrimitiveType decimalPrimitive(String name, PrimitiveTypeName typeName) {
        if (typeName == PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY) {
            return new PrimitiveType(
                    Type.Repetition.OPTIONAL,
                    PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY,
                    16,
                    name,
                    OriginalType.DECIMAL);
        }
        return new PrimitiveType(Type.Repetition.OPTIONAL, typeName, name, OriginalType.DECIMAL);
    }

    private static ColumnDescriptor descriptor(String[] path, PrimitiveType primitiveType) {
        return new ColumnDescriptor(path, primitiveType, 0, 0);
    }

    private static ColumnDescriptor descriptor(String[] path, PrimitiveTypeName typeName) {
        return descriptor(path, primitive(path[path.length - 1], typeName));
    }

    private static GroupType mapGroupType(
            String name, PrimitiveTypeName keyType, PrimitiveTypeName valueType) {
        return Types.requiredGroup()
                .as(LogicalTypeAnnotation.mapType())
                .addField(
                        Types.requiredGroup()
                                .addField(Types.required(keyType).named("key"))
                                .addField(Types.required(valueType).named("value"))
                                .named("key_value"))
                .named(name);
    }
