                        DataFormatConverters.getConverterForDataType(pojoDataType);
        TestPojo pojo = new TestPojo("Alice", 42);

        TestPojo result = converter.toExternal(converter.toInternal(pojo));

        assertAll(
                () -> assertInstanceOf(PojoConverter.class, converter),
                () -> assertEquals("Alice", result.name),
                () -> assertEquals(42, result.age));
    }

