    @Test
    void testUnsupportedLogicalTypesFailFast() {
        RuntimeException variantException =
                assertThrows(
                        RuntimeException.class,
                        () -> DataFormatConverters.getConverterForDataType(DataTypes.VARIANT()));
        RuntimeException uuidException =
                assertThrows(
                        RuntimeException.class,
                        () -> DataFormatConverters.getConverterForDataType(DataTypes.UUID()));
        RuntimeException intervalException =
                assertThrows(
                        RuntimeException.class,
                        () ->
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.INTERVAL(DataTypes.DAY())));

        assertAll(
                () -> assertEquals("Not support dataType: VARIANT", variantException.getMessage()),
                () -> assertEquals("Not support dataType: UUID", uuidException.getMessage()),
                () ->
                        assertEquals(
                                "Not support dataType: INTERVAL DAY(2)",
                                intervalException.getMessage()));
    }

    @Test
    void testUnsupportedConversionClassesThrowDescriptiveExceptions() {
        DataType invalidVarchar =
                DataTypes.of(new LegacyTypeInformationType<>(LogicalTypeRoot.VARCHAR, Types.INT));
        DataType invalidDecimal =
                DataTypes.of(
                        new LegacyTypeInformationType<>(LogicalTypeRoot.DECIMAL, Types.STRING));
        DataType invalidTimestamp =
                DataTypes.of(
                        new LegacyTypeInformationType<>(
                                LogicalTypeRoot.TIMESTAMP_WITHOUT_TIME_ZONE, Types.STRING));
        DataType invalidLocalTimestamp =
                DataTypes.of(
                        new LegacyTypeInformationType<>(
                                LogicalTypeRoot.TIMESTAMP_WITH_LOCAL_TIME_ZONE, Types.STRING));

        RuntimeException varcharException =
                assertThrows(
                        RuntimeException.class,
                        () -> DataFormatConverters.getConverterForDataType(invalidVarchar));
        RuntimeException decimalException =
                assertThrows(
                        RuntimeException.class,
                        () -> DataFormatConverters.getConverterForDataType(invalidDecimal));
        RuntimeException timestampException =
                assertThrows(
                        RuntimeException.class,
                        () -> DataFormatConverters.getConverterForDataType(invalidTimestamp));
        RuntimeException localTimestampException =
                assertThrows(
                        RuntimeException.class,
                        () -> DataFormatConverters.getConverterForDataType(invalidLocalTimestamp));

        assertAll(
                () ->
                        assertEquals(
                                "Not support class for VARCHAR: class java.lang.Integer",
                                varcharException.getMessage()),
                () ->
                        assertEquals(
                                "Not support conversion class for DECIMAL: class java.lang.String",
                                decimalException.getMessage()),
                () ->
                        assertEquals(
                                "Not support conversion class for TIMESTAMP WITHOUT TIME ZONE: class java.lang.String",
                                timestampException.getMessage()),
                () ->
                        assertEquals(
                                "Not support conversion class for TIMESTAMP WITH LOCAL TIME ZONE: class java.lang.String",
                                localTimestampException.getMessage()));
    }

