    /** Simple POJO used to exercise the legacy composite-type conversion path. */
    public static class TestPojo {
        public String name;
        public int age;

        public TestPojo() {}

        public TestPojo(String name, int age) {
            this.name = name;
            this.age = age;
        }
    }

    /** Simple POJO used to exercise the generic serializer based RAW conversion path. */
    public static class TestRawValue implements java.io.Serializable {
        private static final long serialVersionUID = 1L;

        public String value;
        public int number;

        public TestRawValue() {}

        public TestRawValue(String value, int number) {
            this.value = value;
            this.number = number;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (!(o instanceof TestRawValue)) {
                return false;
            }
            TestRawValue that = (TestRawValue) o;
            return number == that.number && java.util.Objects.equals(value, that.value);
        }

        @Override
        public int hashCode() {
            return java.util.Objects.hash(value, number);
        }
    }
